import{_ as i,a0 as s,w as p,s as u,I as n,x as e,a1 as r,A as o,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"尝试、学习、修改：新 IT 领导者的代码 | LCTT x X-CMD","titleTemplate":false,"description":"尝试、学习、修改：新 IT 领导者的代码 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"尝试、学习、修改：新 IT 领导者的代码 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"尝试、学习、修改：新 IT 领导者的代码 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180306 Try, learn, modify- The new IT leader-s code","title":"尝试、学习、修改：新 IT 领导者的代码","tag":"201808","desc":""},"relativePath":"201808/20180306 Try, learn, modify- The new IT leader-s code.md","filePath":"[post].md"}'),d={name:"201808/20180306 Try, learn, modify- The new IT leader-s code.md"};function m(T,t,f,g,y,C){const l=s("Link");return p(),u("div",null,[t[26]||(t[26]=n("h1",{id:"尝试、学习、修改-新-it-领导者的代码",tabindex:"-1"},[e("尝试、学习、修改：新 IT 领导者的代码 "),n("a",{class:"header-anchor",href:"#尝试、学习、修改-新-it-领导者的代码","aria-label":"Permalink to “尝试、学习、修改：新 IT 领导者的代码”"},"​")],-1)),t[27]||(t[27]=n("blockquote",null,[n("p",null,"随着创新步伐的增加, 长期规划变得越来越困难。让我们重新思考一下我们对变化的反应方式。")],-1)),t[28]||(t[28]=n("p",null,[n("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/ship_wheel_gear_devops_kubernetes.png?itok=xm4a74Kv",alt:""})],-1)),t[29]||(t[29]=n("p",null,"几乎每一天，新的技术发展都可能会动摇那些甚至最复杂、最完善的商业计划。组织经常发现自己需要不断努力适应新的环境，这导致了他们对未来规划的转变。",-1)),n("p",null,[t[2]||(t[2]=e("根据 CompTIA 2017 年的",-1)),r(l,{href:"https://www.cio.com/article/3246027/enterprise-architecture/the-death-of-long-term-it-planning.html?upd=1515780110970"},{default:o(()=>[...t[0]||(t[0]=[e("研究",-1)])]),_:1}),t[3]||(t[3]=e("，目前只有 34% 的公司正在制定超过 12 个月的 IT 架构计划。从长期计划转变的一个原因是：商业环境变化如此之快，以至于几乎不可能进一步规划未来。",-1)),r(l,{href:"https://www.cio.com/article/3246027/enterprise-architecture/the-death-of-long-term-it-planning.html?upd=1515780110970"},{default:o(()=>[...t[1]||(t[1]=[e("CIO.com 说道",-1)])]),_:1}),t[4]||(t[4]=e("，“如果你的公司正视图制定一项将持续五到十年的计划，那就忘了它。”",-1))]),t[30]||(t[30]=a('<p>我听过来自世界各地无数客户和合作伙伴的类似声明：技术创新正以一种前所未有的速度发生着。</p><p>其结果是长期规划已不复存在。如果我们要在这个新世界取得成功，我们需要以不同的方式思考我们运营组织的方式。</p><h3 id="计划是怎么死的" tabindex="-1">计划是怎么死的 <a class="header-anchor" href="#计划是怎么死的" aria-label="Permalink to “计划是怎么死的”">​</a></h3><p>正如我在《<ruby>开放式组织<rt>The Open Organization</rt></ruby>》中写的那样，传统经营组织针对工业经济进行了优化。他们采用等级结构和严格规定的流程，以实现地位竞争优势。要取得成功，他们必须确定他们想要实现的战略地位。然后，他们必须制定并规划实现目标的计划，并以最有效的方式执行这些计划，通过协调活动和推动合规性。</p><p>管理层的职责是优化这一过程：计划、规定、执行。包括：让我们想象一个有竞争力的优势地位；让我们来配置组织以最终达成目标；然后让我们通过确保组织的所有方面都遵守规定来推动执行。这就是我所说的“机械管理”，对于不同时期来说它都是一个出色的解决方案。</p><p>在当今动荡不定的世界中，我们预测和定义战略位置的能力正在下降，因为变化的速度，新变量的引入速度正在加速。传统的、长期的、战略性规划和执行不像以前那么有效。</p><p>如果长期规划变得如此困难，那么规定必要的行为就更具有挑战性。并且衡量对计划的合规性几乎是不可能的。</p><p>这一切都极大地影响了人们的工作方式。与过去传统经营组织中的工人不同，他们为自己能够重复行动而感到自豪，几乎没有变化和舒适的确定性 —— 今天的工人在充满模糊性的环境中运作。他们的工作需要更大的创造力、直觉和批判性判断 —— 更多的需要背离过去的“常规”，以适应当今的新情况。</p><p>以这种新方式工作对于价值创造变得更加重要。我们的管理系统必须专注于构建结构，系统和流程，以帮助创建积极主动的工人，他们能够以快速和敏捷的方式进行创新和行动。</p><p>我们需要提出一个不同的解决方案来优化组织，以适应不同的经济时代，从自下而上而不是自上而下开始。我们需要替换过去的三步骤 —— 计划、规定、执行，以一种更适应当今动荡天气的方法来取得成功 —— 尝试、学习、修改。</p><h3 id="尝试、学习、修改" tabindex="-1">尝试、学习、修改 <a class="header-anchor" href="#尝试、学习、修改" aria-label="Permalink to “尝试、学习、修改”">​</a></h3><p>因为环境变化如此之快，而且几乎没有任何预警，并且因为我们需要采取的步骤不再提前计划，我们需要培养鼓励创造性尝试和错误的环境，而不是坚持对五年计划的忠诚。以下是以这种方式开始工作的一些暗示：</p>',12)),n("ul",null,[t[9]||(t[9]=n("li",null,[n("strong",null,"更短的计划周期（尝试）。"),e(" 管理者需要考虑的是他们可以快速尝试的短期实验，而不是在长期战略方向上苦恼。他们应该寻求方法来帮助他们的团队承担计算风险，并利用他们掌握的数据来对最有利的路径做出最好的猜测。他们可以通过降低开销和让团队自由快速尝试新方法来做到这一点。")],-1)),n("li",null,[t[6]||(t[6]=n("strong",null,"更高的失败容忍度（学习）。",-1)),t[7]||(t[7]=e(" 更多的实验频率意味着更大的失败机会。与传统组织相比，富有创造力和有弹性的组织",-1)),r(l,{href:"https://opensource.com/open-organization/16/12/building-culture-innovation-your-organization"},{default:o(()=>[...t[5]||(t[5]=[e("对失败的容忍度要高得多",-1)])]),_:1}),t[8]||(t[8]=e("。管理者应将失败视为学习的机会，在他们的团队正在运行的测试中收集反馈的时刻。",-1))]),t[10]||(t[10]=n("li",null,[n("strong",null,"更具适应性的结构（修改）。"),e(" 能够轻松修改组织结构和战略方向，以及在条件需要时愿意这样做，是确保组织能够根据快速变化的环境条件发展的关键。管理者不能再拘泥于任何想法，因为这个想法证明自己对实现短期目标很有用。")],-1))]),t[31]||(t[31]=n("p",null,"如果长期计划已经消亡，那么就可以进行长期的短期实验。尝试，学习和修改，这是在不确定时期前进的最佳途径。",-1)),n("p",null,[r(l,{href:"https://opensource.com/open-organization/resources/newsletter"},{default:o(()=>[...t[11]||(t[11]=[e("订阅我们的每周实事通讯",-1)])]),_:1}),t[12]||(t[12]=e("以了解有关开源组织的更多信息。",-1))]),t[32]||(t[32]=n("hr",null,null,-1)),n("p",null,[t[14]||(t[14]=e("via: ",-1)),r(l,{href:"https://opensource.com/open-organization/18/3/try-learn-modify"},{default:o(()=>[...t[13]||(t[13]=[e("https://opensource.com/open-organization/18/3/try-learn-modify",-1)])]),_:1})]),n("p",null,[t[18]||(t[18]=e("作者：",-1)),r(l,{href:"https://opensource.com/users/remyd"},{default:o(()=>[...t[15]||(t[15]=[e("Jim Whitehurst",-1)])]),_:1}),t[19]||(t[19]=e(" 译者：",-1)),r(l,{href:"https://github.com/MjSeven"},{default:o(()=>[...t[16]||(t[16]=[e("MjSeven",-1)])]),_:1}),t[20]||(t[20]=e(" 校对：",-1)),r(l,{href:"https://github.com/wxy"},{default:o(()=>[...t[17]||(t[17]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[23]||(t[23]=e("本文由 ",-1)),r(l,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[21]||(t[21]=[e("LCTT",-1)])]),_:1}),t[24]||(t[24]=e(" 原创编译，",-1)),r(l,{href:"https://linux.cn/"},{default:o(()=>[...t[22]||(t[22]=[e("Linux中国",-1)])]),_:1}),t[25]||(t[25]=e(" 荣誉推出",-1))])])}const b=i(d,[["render",m]]);export{w as __pageData,b as default};
